package dev.eugheist.tc4modern;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import thaumcraft.api.aspects.*;
/** Original lesser-ring charge, inventory vis recharge and empty-shield delay. */
@EventBusSubscriber(modid=TC4Modern.MODID)
public final class RunicRingShield {
 // Original handler shares dirty and rechargeDelay across players; retain that multiplayer quirk.
 static boolean dirty=true;static int rechargeDelay;
 static final java.util.Map<java.util.UUID,long[]> clocks=new java.util.HashMap<>();
 @SubscribeEvent static void login(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent event){var p=event.getEntity();p.getPersistentData().remove("TC4RunicInfo");p.getPersistentData().putInt("TC4RunicCharge",0);p.getPersistentData().putInt("TC4RunicMax",0);clocks.remove(p.getUUID());dirty=true;send(p,0,0);}
 @SubscribeEvent static void logout(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent event){clocks.remove(event.getEntity().getUUID());}
 static int[] info(net.minecraft.world.entity.player.Player p){int[] out=new int[5];for(var stack:p.getArmorSlots())out[0]+=RunicAccessories.charge(stack);for(int i=0;i<4;i++){var stack=BaublesInventory.of(p).getItem(i);out[0]+=RunicAccessories.charge(stack);if(stack.getItem() instanceof RunicAccessories.RunicItem r&&r.kind.upgrade>0)out[r.kind.upgrade]++;}return out;}
 static void send(net.minecraft.world.entity.player.Player p,int charge,int max){if(p instanceof net.minecraft.server.level.ServerPlayer server&&!(server instanceof net.neoforged.neoforge.common.util.FakePlayer))net.neoforged.neoforge.network.PacketDistributor.sendToPlayer(server,new Charge(charge,max));}
 @SubscribeEvent static void tick(net.neoforged.neoforge.event.tick.PlayerTickEvent.Post event){var p=event.getEntity();if(p.level().isClientSide)return;var tag=p.getPersistentData();int[] values;
  if(dirty||p.tickCount%40==0||!tag.contains("TC4RunicInfo")){values=info(p);tag.putIntArray("TC4RunicInfo",values);dirty=false;}else values=tag.getIntArray("TC4RunicInfo");
  int max=values[0],old=tag.getInt("TC4RunicMax"),charge=Math.min(max,tag.getInt("TC4RunicCharge"));var clock=clocks.computeIfAbsent(p.getUUID(),id->new long[5]);long time=System.currentTimeMillis();
  if(rechargeDelay>0)rechargeDelay--;else if(charge<max&&clock[0]<time){var cost=new AspectList().add(Aspect.AIR,RunicConfig.cost()).add(Aspect.EARTH,RunicConfig.cost());for(int slot=35;slot>=0;slot--){var wand=p.getInventory().getItem(slot);if(WandData.isWand(wand)&&FociContent.consumeAllVis(wand,p,cost,true)){charge++;clock[0]=time+RunicConfig.speed()-values[1]*500;break;}}}
  boolean changed=charge!=tag.getInt("TC4RunicCharge")||max!=old;tag.putInt("TC4RunicMax",max);tag.putInt("TC4RunicCharge",charge);if(changed)send(p,charge,max);
 }
 @SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.LOW) static void damage(net.neoforged.neoforge.event.entity.living.LivingIncomingDamageEvent event){if(!(event.getEntity() instanceof net.minecraft.world.entity.player.Player p)||p.level().isClientSide)return;var source=event.getSource();if(source.is(net.minecraft.world.damagesource.DamageTypes.DROWN)||source.is(net.minecraft.world.damagesource.DamageTypes.STARVE)||source.is(net.minecraft.world.damagesource.DamageTypes.WITHER)||source.is(net.minecraft.world.damagesource.DamageTypes.FELL_OUT_OF_WORLD))return;var tag=p.getPersistentData();int charge=tag.getInt("TC4RunicCharge");float damage=event.getAmount();if(charge<=0||damage<=0)return;int remaining=charge>damage?(int)(charge-damage):0;event.setAmount(Math.max(0,damage-charge));var values=info(p);var clock=clocks.computeIfAbsent(p.getUUID(),id->new long[5]);long time=System.currentTimeMillis();
  if(remaining==0){if(values[2]>0&&clock[2]<time){clock[2]=time+20000;p.level().explode(p,p.getX(),p.getY()+p.getBbHeight()/2,p.getZ(),1.5f+values[2]*.5f,false,net.minecraft.world.level.Level.ExplosionInteraction.NONE);}
   if(values[3]>0&&clock[3]<time){clock[3]=time+20000;p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.REGENERATION,240,values[3]));p.level().playSound(null,p.blockPosition(),InfusionContent.MatrixEntity.sound("runicshieldeffect"),net.minecraft.sounds.SoundSource.PLAYERS,1,1);}
   if(values[4]>0&&clock[4]<time){clock[4]=time+60000;remaining=Math.min(values[0],8*values[4]);dirty=true;p.level().playSound(null,p.blockPosition(),InfusionContent.MatrixEntity.sound("runicshieldcharge"),net.minecraft.sounds.SoundSource.PLAYERS,1,1);}
   if(remaining<=0)rechargeDelay=RunicConfig.delay();
  }
  tag.putInt("TC4RunicCharge",remaining);if(p.level() instanceof net.minecraft.server.level.ServerLevel level){int target=source.getDirectEntity()!=null?source.getDirectEntity().getId():-1;if(source.is(net.minecraft.world.damagesource.DamageTypes.FALL))target=-2;if(source.is(net.minecraft.world.damagesource.DamageTypes.FALLING_ANVIL)||source.is(net.minecraft.world.damagesource.DamageTypes.FALLING_BLOCK))target=-3;net.neoforged.neoforge.network.PacketDistributor.sendToPlayersNear(level,null,p.getX(),p.getY(),p.getZ(),64,new Impact(p.getId(),target));}send(p,remaining,values[0]);
 }
 @SubscribeEvent static void tooltip(net.neoforged.neoforge.event.entity.player.ItemTooltipEvent event){int charge=RunicAccessories.charge(event.getItemStack());if(charge>0)event.getToolTip().add(net.minecraft.network.chat.Component.translatable("item.runic.charge").append(" +"+charge).withStyle(net.minecraft.ChatFormatting.GOLD));}
 public record Impact(int source,int target) implements net.minecraft.network.protocol.common.custom.CustomPacketPayload {
  public static final Type<Impact> TYPE=new Type<>(AlchemyContent.id("runic_impact"));public static final net.minecraft.network.codec.StreamCodec<net.minecraft.network.RegistryFriendlyByteBuf,Impact> CODEC=net.minecraft.network.codec.StreamCodec.composite(net.minecraft.network.codec.ByteBufCodecs.INT,Impact::source,net.minecraft.network.codec.ByteBufCodecs.INT,Impact::target,Impact::new);public Type<? extends net.minecraft.network.protocol.common.custom.CustomPacketPayload> type(){return TYPE;}
 }
 public record Charge(int current,int max) implements net.minecraft.network.protocol.common.custom.CustomPacketPayload {
  public static final Type<Charge> TYPE=new Type<>(AlchemyContent.id("runic_charge"));public static final net.minecraft.network.codec.StreamCodec<net.minecraft.network.RegistryFriendlyByteBuf,Charge> CODEC=net.minecraft.network.codec.StreamCodec.composite(net.minecraft.network.codec.ByteBufCodecs.INT,Charge::current,net.minecraft.network.codec.ByteBufCodecs.INT,Charge::max,Charge::new);@Override public Type<? extends net.minecraft.network.protocol.common.custom.CustomPacketPayload> type(){return TYPE;}
 }
 @EventBusSubscriber(modid=TC4Modern.MODID,bus=EventBusSubscriber.Bus.MOD)public static final class Network {@SubscribeEvent static void payload(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent event){event.registrar("tc4-basics-1").playToClient(Impact.TYPE,Impact.CODEC,(packet,context)->context.enqueueWork(()->RunicShieldClient.receive(packet)));event.registrar("tc4-basics-1").playToClient(Charge.TYPE,Charge.CODEC,(packet,context)->context.enqueueWork(()->Client.receive(packet)));}}
 @EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)public static final class Client {private static int charge,max;static void receive(Charge packet){charge=packet.current;max=packet.max;}@SubscribeEvent static void loggingOut(net.neoforged.neoforge.client.event.ClientPlayerNetworkEvent.LoggingOut event){charge=0;max=0;}@SubscribeEvent static void render(net.neoforged.neoforge.client.event.RenderGuiEvent.Post event){var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.options.hideGui||mc.gameMode==null||!mc.gameMode.canHurtPlayer()||max<=0||charge<=0)return;var gui=event.getGuiGraphics();// Original renderRunicArmorBar: depth off, SRC_ALPHA/ONE_MINUS_SRC_ALPHA; modern HUD layers sit at higher z and would hide the runes behind the hearts.
gui.flush();com.mojang.blaze3d.systems.RenderSystem.disableDepthTest();com.mojang.blaze3d.systems.RenderSystem.depthMask(false);com.mojang.blaze3d.systems.RenderSystem.enableBlend();com.mojang.blaze3d.systems.RenderSystem.defaultBlendFunc();int x=gui.guiWidth()/2-91,y=gui.guiHeight()-39;var texture=AlchemyContent.id("textures/misc/particles.png");for(int i=0;i<(float)charge/max*10;i++){gui.blit(texture,x+i*8,y,160,16,9,9);com.mojang.blaze3d.systems.RenderSystem.setShaderColor(1,.75f,.24f,(float)Math.sin(mc.player.tickCount/4f+i)*.4f+.6f);gui.pose().pushPose();gui.pose().translate(x+i*8,y,0);gui.pose().scale(.5f,.5f,1);gui.blit(texture,0,0,i*16,96,16,16);gui.pose().popPose();com.mojang.blaze3d.systems.RenderSystem.setShaderColor(1,1,1,1);}com.mojang.blaze3d.systems.RenderSystem.disableBlend();com.mojang.blaze3d.systems.RenderSystem.depthMask(true);com.mojang.blaze3d.systems.RenderSystem.enableDepthTest();}}
}
